import type { Difficulty, Puzzle } from './types'

// Puzzles come from the Sudoku Exchange puzzle bank (generated by QQWing, rated
// with Sukaku Explainer) via scripts/import-puzzles.ts, which also verified that
// each has exactly one solution. They are served as static files next to the app.

export interface BankEntry {
  id: string
  givens: string // 81 digits, 0 for empty
  solution: string // 81 digits
  rating: number // Sukaku Explainer rating
}

const PLAYED_KEY = 'sudoku.played'
const PLAYED_LIMIT = 500

export const bankUrl = (difficulty: Difficulty) =>
  `${import.meta.env.BASE_URL}puzzles/${difficulty.toLowerCase()}.json`

function readPlayed(): string[] {
  try {
    const played = JSON.parse(localStorage.getItem(PLAYED_KEY) ?? '[]')
    return Array.isArray(played) ? played : []
  } catch {
    return []
  }
}

function markPlayed(id: string): void {
  try {
    localStorage.setItem(PLAYED_KEY, JSON.stringify([...readPlayed(), id].slice(-PLAYED_LIMIT)))
  } catch {
    // Avoiding repeats is best-effort.
  }
}

/** Picks a random puzzle of the given difficulty, avoiding recently played ones. */
export async function fetchPuzzle(difficulty: Difficulty, signal?: AbortSignal): Promise<Puzzle> {
  const res = await fetch(bankUrl(difficulty), { signal })
  if (!res.ok) throw new Error(`Could not load ${difficulty} puzzles (${res.status})`)
  const bank: BankEntry[] = await res.json()

  const played = new Set(readPlayed())
  const fresh = bank.filter((p) => !played.has(p.id))
  const pool = fresh.length > 0 ? fresh : bank
  const entry = pool[Math.floor(Math.random() * pool.length)]
  markPlayed(entry.id)

  return {
    id: entry.id,
    givens: [...entry.givens].map(Number),
    solution: [...entry.solution].map(Number),
    difficulty,
  }
}
